In hookRoutes.ts, mirror the spawn/mode gates: read the header and require it to equal the body sessionId before dispatching. Minimal change at the route (no dispatcher signature change):

router.post('/hooks/dispatch', validateBody(hookDispatchSchema), async (req, res) => {
  try {
    const callerSessionId = req.headers['x-session-id'] as string | undefined;
    if (!callerSessionId || callerSessionId !== req.body.sessionId) {
