Add to maestro-ui/src/stores/useActiveSpellsStore.ts (or a small util), a hook that resolves ensemble colors:

```ts
import { useEnsembleStore } from './useEnsembleStore';
import { resolveSpellColorId } from '../app/constants/spellColors';
import type { RingSpec } from '../utils/spellRings';

export function useSpellRingSpecs(maestroSessionId: string | null | undefined): RingSpec[] {
  const activeSpells = useActiveSpellsForSession(maestroSessionId ?? null);
  const ensembles = useEnsembleStore((s) => s.ensembles);
  return useMemo<RingSpec[]>(
    () => activeSpells.map((s) => {
      const ens = s.ensembleId ? ensembles.find((e) => e.id === s.ensembleId) : undefined;
      return {
        spellName: s.spellName,
        colorId: s.colorId,
        ensembleId: s.ensembleId,
        ensembleColorId: ens ? resolveSpellColorId(ens.color) : undefined,
      };
    }),
    [activeSpells, ensembles],
  );
}
```

