```ts
// spellRings.ts — add:
export function spellRingAriaLabel(
  sessionName: string,
  rings: ReadonlyArray<RingSpec>,
  ensembleName?: string,
): string | undefined {
  if (rings.length === 0) return undefined;
  const names = rings.map(r => r.spellName).join(', ');
  const plural = rings.length === 1 ? 'spell' : 'spells';
  const base = `Session ${sessionName} — ${rings.length} ${plural}: ${names}`;
  return ensembleName ? `${base} (in ensemble "${ensembleName}")` : base;
}
```

